    "rawCss": "#wemd {\n    padding: 30px 20px;\n    max-width: 677px;\n    margin: 0 auto;\n    /* 混合字体栈：西文Times + 中文宋体 */\n    font-family: \"Times New Roman\", \"Songti SC\", \"SimSun\", serif;\n    color: #000;\n    background-color: transparent;\n    /* 透明背景，兼容微信深色模式 */\n    word-break: break-word;\n}\n\n/* 正文 - 移除首行缩进，改用段间距适应移动端 */\n#wemd p {\n    margin: 16px 0;\n    line-height: 1.7;\n    text-align: justify;\n    text-indent: 0;\n    color: #1a1a1a;\n    font-size: 16px;\n}\n\n/* 一级标题 - 居中论文题 */\n#wemd h1 {\n    margin: 40px 0 30px;\n    text-align: center;\n    line-height: 1.4;\n}\n\n#wemd h1 .content {\n    font-size: 22px;\n    font-weight: bold;\n    color: #000;\n}\n\n#wemd h1 .prefix,\n#wemd h1 .suffix {\n    display: none;\n}\n\n/* 二级标题 - 章节 Section */\n#wemd h2 {\n    margin: 30px 0 15px;\n    text-align: left;\n    border-bottom: 2px solid #000;\n    /* 加粗底线 */\n    padding-bottom: 8px;\n}\n\n#wemd h2 .content {\n    font-size: 18px;\n    font-weight: bold;\n    color: #000;\n}\n\n#wemd h2 .prefix,\n#wemd h2 .suffix {\n    display: none;\n}\n\n/* 三级标题 - Subsection */\n#wemd h3 {\n    margin: 20px 0 10px;\n}\n\n#wemd h3 .content {\n    font-size: 16px;\n    font-weight: bold;\n    color: #800000;\n    /* 栗色，区分层级 */\n}\n\n#wemd h3 .prefix,\n#wemd h3 .suffix {\n    display: none;\n}\n\n/* 四级标题 */\n#wemd h4 {\n    margin: 15px 0 5px;\n}\n\n#wemd h4 .content {\n    font-size: 16px;\n    font-weight: bold;\n    font-style: italic;\n    /* 斜体标题 */\n    color: #333;\n}\n\n#wemd h4 .prefix,\n#wemd h4 .suffix {\n    display: none;\n}\n\n/* 引用 - 简洁边框 */\n#wemd .multiquote-1 {\n    margin: 20px 0;\n    padding: 16px 20px;\n    background: #fafafa;\n    border: 1px solid #ddd;\n    border-left: 4px solid #666;\n}\n\n#wemd .multiquote-1 p {\n    color: #555;\n    font-size: 15px;\n    margin: 0;\n    line-height: 1.6;\n    text-indent: 0;\n}\n\n#wemd .multiquote-2 {\n    margin: 18px 0 18px 20px;\n    padding: 14px 18px;\n    background: #fafafa;\n    border: 1px solid #ddd;\n}\n\n#wemd .multiquote-2 p {\n    color: #555;\n    font-size: 15px;\n    margin: 0;\n}\n\n#wemd .multiquote-3 {\n    margin: 16px 0 16px 20px;\n    padding: 12px 16px;\n    background: #fcfcfc;\n    border: 1px solid #e0e0e0;\n}\n\n#wemd .multiquote-3 p {\n    color: #555;\n    font-size: 15px;\n    margin: 0;\n}\n\n/* 列表 */\n#wemd ul {\n    list-style: disc;\n    padding-left: 20px;\n    margin: 16px 0;\n}\n\n#wemd ul ul {\n    list-style-type: square;\n    margin-top: 5px;\n}\n\n#wemd ol {\n    list-style: decimal;\n    padding-left: 20px;\n    margin: 16px 0;\n}\n\n#wemd ol ol {\n    list-style-type: lower-alpha;\n}\n\n#wemd li section {\n    color: #333;\n    line-height: 1.6;\n}\n\n/* 链接 - 经典深蓝 */\n#wemd a {\n    color: #000080;\n    text-decoration: underline;\n}\n\n/* 加粗 */\n#wemd strong {\n    color: #000;\n    font-weight: bold;\n}\n\n/* 斜体 */\n#wemd em {\n    font-style: italic;\n    color: #000;\n}\n\n/* 加粗斜体 */\n#wemd em strong {\n    font-weight: bold;\n    font-style: italic;\n    color: #000;\n}\n\n/* 高亮 - 学术标记风格 */\n#wemd mark {\n    background: #fff3cd;\n    color: #000;\n    padding: 0 2px;\n}\n\n/* 删除线 */\n#wemd del {\n    text-decoration: line-through;\n    color: #666;\n    opacity: 0.7;\n}\n\n/* 图片 - 简洁无装饰 */\n#wemd img {\n    display: block;\n    margin: 30px auto;\n    width: 100%;\n    border: 1px solid #ddd;\n}\n\n#wemd figcaption {\n    margin-top: 8px;\n    text-align: center;\n    color: #666;\n    font-size: 14px;\n    font-style: italic;\n}\n\n/* \n * 行内代码 - LaTeX \\texttt 风格 (修复重点)\n * 纯黑文字 + 极淡灰底 + 等宽字体\n */\n#wemd p code,\n#wemd li code {\n    color: #000;\n    /* 纯黑 */\n    background: #f4f4f4;\n    /* 极淡灰 */\n    border: 1px solid #eee;\n    /* 极细边框 */\n    padding: 1px 4px;\n    margin: 0 2px;\n    border-radius: 2px;\n    font-size: 14px;\n    font-family: \"Courier New\", Courier, monospace;\n    /* 强制等宽 */\n}\n\n/* 代码块 - 简单的学术风格 */\n/* 注意：不要设置 color，让语法高亮主题控制文字颜色 */\n#wemd pre code.hljs {\n    background: #f9f9f9;\n    border: 1px solid #ccc;\n    /* color 由 .hljs 语法高亮主题控制 */\n    font-family: \"Courier New\", monospace;\n    font-size: 13px;\n    padding: 12px;\n    border-radius: 0;\n    /* 直角 */\n    overflow-x: auto;\n    white-space: pre;\n    min-width: max-content;\n}\n\n/* 如果没有语法高亮，设置默认颜色 */\n#wemd pre code:not(.hljs) {\n    color: #333;\n}\n\n/* 表格 - 经典三线表 */\n#wemd table {\n    width: 100%;\n    border-collapse: collapse;\n    margin: 20px 0;\n    font-size: 14px;\n    border-top: 2px solid #000;\n    border-bottom: 2px solid #000;\n}\n\n#wemd table tr th {\n    border-bottom: 1px solid #000;\n    padding: 10px 5px;\n    font-weight: bold;\n    text-align: center;\n    background: #fff;\n}\n\n#wemd table tr td {\n    padding: 10px 5px;\n    border: none;\n    text-align: center;\n    color: #333;\n}\n\n/* 隔行微底色 */\n#wemd table tr:nth-child(even) td {\n    background-color: #fafafa;\n}\n\n/* 脚注 */\n#wemd .footnote-word,\n#wemd .footnote-ref {\n    color: #000080;\n}\n\n#wemd .footnotes-sep {\n    border-top: 1px solid #ccc;\n    padding-top: 10px;\n    margin-top: 40px;\n    width: 20%;\n    /* 短线 */\n}\n\n#wemd .footnote-num {\n    font-weight: bold;\n    color: #000;\n    margin-right: 4px;\n    vertical-align: super;\n    font-size: 10px;\n}\n\n#wemd .footnote-item p {\n    color: #666;\n    font-size: 12px;\n    margin: 4px 0;\n}\n\n/* 公式 */\n#wemd .block-equation svg {\n    max-width: 100% !important;\n}\n\n#wemd .inline-equation svg {\n    max-width: 100%;\n    vertical-align: middle;\n}\n\n/* 提示块 - 学术风格 */\n#wemd .callout {\n    margin: 20px 0;\n    padding: 16px 20px;\n    border: 1px solid #ddd;\n    border-radius: 0;\n    background: #fafafa;\n}\n\n#wemd .callout-title {\n    font-weight: bold;\n    margin-bottom: 8px;\n    font-size: 14px;\n    text-transform: uppercase;\n    color: #000;\n}\n\n#wemd .callout-icon {\n    margin-right: 6px;\n}\n\n#wemd .callout-note {\n    border-left: 4px solid #666;\n    background: #f5f5f5;\n}\n\n#wemd .callout-tip {\n    border-left: 4px solid #555;\n    background: #f5f5f5;\n}\n\n#wemd .callout-important {\n    border-left: 4px solid #888;\n    background: #f5f5f5;\n}\n\n#wemd .callout-warning {\n    border-left: 4px solid #999;\n    background: #f5f5f5;\n}\n\n#wemd .callout-caution {\n    border-left: 4px solid #000;\n    background: #f5f5f5;\n}/* Imageflow CSS */\n#wemd .imageflow-layer1 {\n    margin-top: 1em;\n    margin-bottom: 0.5em;\n    /* white-space: normal; */\n    border: 0px none;\n    padding: 0px;\n    overflow: hidden;\n}\n\n#wemd .imageflow-layer2 {\n    white-space: nowrap;\n    width: 100%;\n    overflow-x: scroll;\n}\n\n#wemd .imageflow-layer3 {\n    display: inline-block;\n    word-wrap: break-word;\n    white-space: normal;\n    vertical-align: top;\n    width: 80%;\n    margin-right: 10px;\n    flex-shrink: 0;\n}\n\n#wemd .imageflow-img {\n    display: block;\n    width: 100%;\n    height: auto;\n    max-height: 300px;\n    object-fit: contain;\n    border-radius: 4px;\n}\n\n#wemd .imageflow-caption {\n    text-align: center;\n    margin-top: 0px;\n    padding-top: 0px;\n    color: #888;\n}",
