    "accent": "#356348",
    "canvas": "#f7f7f4",
    "body": "#34362f",
    "heading": "#20221e",
    "rawCss": "#wemd {\n  padding: 30px 22px;\n  max-width: 677px;\n  margin: 0 auto;\n  font-family: \"Optima\", \"Georgia\", \"PingFang SC\", \"Microsoft YaHei\", serif;\n  color: #2F3E32;\n  background-color: transparent;\n  /* 透明背景，兼容微信深色模式 */\n  word-break: break-word;\n}\n\n/* 段落 */\n#wemd p {\n  margin-top: 26px;\n  margin-bottom: 26px;\n  line-height: 2.0;\n  letter-spacing: 0.5px;\n  text-align: justify;\n  color: #3A4D39;\n  font-size: 16px;\n}\n\n/* 一级标题 */\n#wemd h1 {\n  margin-top: 60px;\n  margin-bottom: 50px;\n  text-align: center;\n}\n\n#wemd h1 .content {\n  display: inline-block;\n  font-size: 24px;\n  font-weight: normal;\n  color: #1A261D;\n  padding: 12px 24px;\n  border: 1px solid #739072;\n  border-radius: 2px;\n  background-color: #F1F4F0;\n  letter-spacing: 2px;\n}\n\n#wemd h1 .prefix,\n#wemd h1 .suffix {\n  display: none;\n}\n\n/* 二级标题 */\n#wemd h2 {\n  margin-top: 50px;\n  margin-bottom: 24px;\n  text-align: left;\n  border-bottom: 1px solid #E8EBE9;\n  padding-bottom: 10px;\n}\n\n#wemd h2 .content {\n  display: inline-block;\n  font-size: 19px;\n  font-weight: 700;\n  color: #4F6F52;\n  padding-left: 12px;\n  border-left: 5px solid #4F6F52;\n  line-height: 1.2;\n  letter-spacing: 1px;\n}\n\n#wemd h2 .prefix,\n#wemd h2 .suffix {\n  display: none;\n}\n\n/* 三级标题 */\n#wemd h3 {\n  margin-top: 40px;\n  margin-bottom: 20px;\n  text-align: center;\n}\n\n#wemd h3 .content {\n  font-size: 17px;\n  font-weight: bold;\n  color: #739072;\n  display: inline-block;\n  border-bottom: 2px dotted #739072;\n  padding-bottom: 4px;\n}\n\n#wemd h3 .prefix,\n#wemd h3 .suffix {\n  display: none;\n}\n\n/* 四级标题 */\n#wemd h4 {\n  margin-top: 30px;\n  margin-bottom: 15px;\n  text-align: left;\n}\n\n#wemd h4 .content {\n  display: inline-block;\n  font-size: 15px;\n  font-weight: 700;\n  color: #fff;\n  background-color: #86A789;\n  padding: 4px 10px;\n  border-radius: 4px;\n  line-height: 1.4;\n}\n\n#wemd h4 .prefix,\n#wemd h4 .suffix {\n  display: none;\n}\n\n/* 列表 */\n#wemd ul {\n  list-style-type: disc;\n  padding-left: 20px;\n  margin: 20px 0;\n  color: #86A789;\n}\n\n#wemd ul li {\n  margin-bottom: 12px;\n  line-height: 1.8;\n}\n\n#wemd li section {\n  color: #3A4D39;\n  font-size: 16px;\n}\n\n/* 有序列表 */\n#wemd ol {\n  list-style-type: decimal;\n  padding-left: 20px;\n  margin: 20px 0;\n  color: #4F6F52;\n  font-weight: bold;\n}\n\n#wemd ul ul {\n  list-style-type: circle;\n  color: #4F6F52;\n  margin-top: 8px;\n}\n\n#wemd ol ol {\n  list-style-type: lower-alpha;\n  color: #739072;\n}\n\n#wemd ol li {\n  margin-bottom: 12px;\n  line-height: 1.8;\n}\n\n#wemd ol li section {\n  color: #3A4D39;\n  font-weight: normal;\n  font-size: 16px;\n}\n\n/* 引用 */\n#wemd .multiquote-1,\n#wemd .multiquote-2,\n#wemd .multiquote-3 {\n  margin: 36px 0;\n  padding: 24px;\n  background-color: #F6F8F6;\n  border: 1px dashed #739072;\n  border-radius: 8px;\n  overflow: visible !important;\n}\n\n#wemd .multiquote-1 p,\n#wemd .multiquote-2 p,\n#wemd .multiquote-3 p {\n  margin: 0;\n  color: #556B58;\n  font-size: 15px;\n  line-height: 1.8;\n  font-family: \"KaiTi\", \"STKaiti\", serif;\n}\n\n/* 链接 */\n#wemd a {\n  color: #4F6F52;\n  text-decoration: none;\n  border-bottom: 1px solid #4F6F52;\n  font-weight: 600;\n  padding-bottom: 0px;\n}\n\n/* 加粗 */\n#wemd strong {\n  color: #1A261D;\n  font-weight: 700;\n  background: linear-gradient(to top, rgba(134, 167, 137, 0.4) 50%, transparent 50%);\n  margin: 0 2px;\n  padding: 0 2px;\n}\n\n/* 斜体 */\n#wemd em {\n  color: #739072;\n  font-style: italic;\n}\n\n#wemd em strong {\n  color: #4F6F52;\n}\n\n/* 高亮 - 浅绿背景 */\n#wemd mark {\n  background: linear-gradient(to top, rgba(134, 167, 137, 0.3) 50%, transparent 50%);\n  color: #1A261D;\n  padding: 0 2px;\n}\n\n/* 删除线 */\n#wemd del {\n  text-decoration: line-through;\n  color: #889E8B;\n}\n\n/* \n * 分隔线 \n * 修复了这里无效的颜色代码 #D2DSD4\n */\n#wemd hr {\n  margin: 60px auto;\n  border: 0;\n  height: 1px;\n  background-color: #D2D4D4;\n  /* 已修正 */\n  width: 60%;\n}\n\n/* 图片 */\n#wemd img {\n  display: block;\n  margin: 40px auto;\n  width: 100%;\n  border-radius: 2px;\n  box-shadow: 0 8px 20px rgba(79, 111, 82, 0.15);\n  padding: 6px;\n  background: #fff;\n  border: 1px solid #eee;\n}\n\n#wemd figcaption {\n  font-size: 13px;\n  color: #889E8B;\n  margin-top: 10px;\n  font-family: serif;\n}\n\n/* 行内代码 */\n#wemd p code,\n#wemd li code {\n  color: #4F6F52;\n  background: #EDF1EE;\n  border: none;\n  padding: 3px 6px;\n  margin: 0 4px;\n  border-radius: 4px;\n  font-size: 14px;\n  font-family: sans-serif;\n}\n\n/* 代码块 */\n/* 代码块 - 注意：不要设置 color，让语法高亮主题控制文字颜色 */\n#wemd pre code.hljs {\n  display: block;\n  padding: 20px;\n  background: #F0F2F0;\n  /* color 由 .hljs 语法高亮主题控制 */\n  font-size: 13px;\n  line-height: 1.6;\n  border-radius: 6px;\n  font-family: sans-serif;\n  overflow-x: auto;\n  white-space: pre;\n  min-width: max-content;\n  border: 1px solid #DCE3DD;\n}\n\n/* 如果没有语法高亮，设置默认深绿色 */\n#wemd pre code:not(.hljs) {\n  color: #3A4D39;\n  background: #F0F2F0;\n  border: 1px solid #DCE3DD;\n}\n\n/* \n * 表格 \n * 修复了这里无效的颜色代码 #D2DSD4\n */\n#wemd table {\n  width: 100%;\n  border-collapse: collapse;\n  margin: 40px 0;\n  font-size: 14px;\n  border: 1px solid #D2D4D4;\n  /* 已修正 */\n}\n\n#wemd table tr th {\n  background: #EDF1EE;\n  color: #4F6F52;\n  font-weight: 700;\n  border: 1px solid #D2D4D4;\n  /* 已修正 */\n  padding: 12px 10px;\n  text-align: left;\n}\n\n#wemd table tr td {\n  border: 1px solid #D2D4D4;\n  /* 已修正 */\n  padding: 12px 10px;\n  color: #555;\n  background: #fff;\n}\n\n/* 脚注 */\n#wemd .footnote-word,\n#wemd .footnote-ref {\n  color: #4F6F52;\n}\n\n#wemd .footnotes-sep {\n  border-top: 1px solid #E8EBE9;\n  padding-top: 20px;\n  margin-top: 60px;\n  font-size: 12px;\n  color: #B0BEB3;\n  text-align: center;\n}\n\n#wemd .footnote-num {\n  font-weight: bold;\n  color: #739072;\n  margin-right: 4px;\n}\n\n#wemd .footnote-item p {\n  color: #889E8B;\n  font-size: 12px;\n  margin: 4px 0;\n}\n\n/* 公式 */\n#wemd .block-equation svg {\n  max-width: 100% !important;\n}\n\n#wemd .inline-equation svg {\n  max-width: 100%;\n  vertical-align: middle;\n}\n\n/* 提示块 - 莫兰迪森林风格 */\n#wemd .callout {\n  margin: 30px 0;\n  padding: 20px;\n  background: #F6F8F6;\n  border: 1px dashed #739072;\n  border-radius: 8px;\n}\n\n#wemd .callout-title {\n  font-weight: 700;\n  margin-bottom: 10px;\n  color: #4F6F52;\n  font-size: 15px;\n}\n\n#wemd .callout-icon {\n  margin-right: 6px;\n}\n\n#wemd .callout-note {\n  border-left: 4px solid #739072;\n}\n\n#wemd .callout-tip {\n  border-left: 4px solid #86A789;\n}\n\n#wemd .callout-important {\n  border-left: 4px solid #4F6F52;\n}\n\n#wemd .callout-warning {\n  border-left: 4px solid #D98C45;\n}\n\n#wemd .callout-caution {\n  border-left: 4px solid #B33D25;\n}/* Imageflow CSS */\n#wemd .imageflow-layer1 {\n    margin-top: 1em;\n    margin-bottom: 0.5em;\n    /* white-space: normal; */\n    border: 0px none;\n    padding: 0px;\n    overflow: hidden;\n}\n\n#wemd .imageflow-layer2 {\n    white-space: nowrap;\n    width: 100%;\n    overflow-x: scroll;\n}\n\n#wemd .imageflow-layer3 {\n    display: inline-block;\n    word-wrap: break-word;\n    white-space: normal;\n    vertical-align: top;\n    width: 80%;\n    margin-right: 10px;\n    flex-shrink: 0;\n}\n\n#wemd .imageflow-img {\n    display: block;\n    width: 100%;\n    height: auto;\n    max-height: 300px;\n    object-fit: contain;\n    border-radius: 4px;\n}\n\n#wemd .imageflow-caption {\n    text-align: center;\n    margin-top: 0px;\n    padding-top: 0px;\n    color: #888;\n}",
