    "rawCss": "#wemd{max-width:677px;margin:0 auto;padding:24px 16px 40px;background:#FFFFFF;font-family:-apple-system,BlinkMacSystemFont,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif;color:#52525B;font-size:15px;line-height:1.8;letter-spacing:0.3px;word-break:break-word;}\n#wemd .article-title{font-size:20px;font-weight:700;color:#27272A;line-height:1.3;margin-bottom:8px;letter-spacing:0.3px;}\n#wemd .article-subtitle{font-size:12px;color:#A1A1AA;margin-bottom:32px;padding-bottom:12px;border-bottom:1px solid #E4E4E7;}\n#wemd h1{font-size:18px;font-weight:800;color:#27272A;margin:32px 0 12px;padding-bottom:10px;border-bottom:1px solid #E4E4E7;line-height:1.4;letter-spacing:0.3px;}\n#wemd h2{font-size:16px;font-weight:700;color:#27272A;margin:28px 0 10px;padding-left:12px;border-left:3px solid #52525B;line-height:1.4;letter-spacing:0.3px;}\n#wemd h3{font-size:15px;font-weight:700;color:#52525B;margin:20px 0 8px;line-height:1.4;letter-spacing:0.3px;}\n#wemd p{margin:18px 0;color:#52525B;line-height:1.8;font-size:15px;}\n#wemd blockquote{margin:24px 0;padding:18px 20px;background:#FAFAFA;border-left:3px solid #52525B;color:#52525B;font-size:15px;line-height:1.8;border-radius:0 2px 2px 0;}\n#wemd pre{margin:20px 0;overflow-x:auto;border-radius:2px;}\n#wemd pre code{background:#1E293B;color:#E2E8F0;padding:16px;border-radius:2px;overflow-x:auto;font-family:'SF Mono',Monaco,'Source Code Pro','Fira Code','Cascadia Code',monospace;font-size:12px;line-height:1.75;margin:20px 0;}\n#wemd :not(pre)>code{background:#F4F4F5;padding:1px 5px;border-radius:2px;font-family:'SF Mono',Monaco,'Source Code Pro','Fira Code','Cascadia Code',monospace;font-size:13px;color:#52525B;border:1px solid #E4E4E7;}\n#wemd ul{margin:18px 0;padding-left:22px;list-style:disc;}\n#wemd ol{margin:18px 0;padding-left:22px;}\n#wemd li{margin:8px 0;color:#52525B;line-height:1.8;font-size:15px;}\n#wemd strong{font-weight:700;color:#27272A;background:#F4F4F5;padding:1px 5px;border-radius:2px;}\n#wemd em{font-style:italic;color:#A1A1AA;}\n#wemd a{color:#52525B;text-decoration:none;border-bottom:1px solid #52525B;font-weight:600;}\n#wemd img{max-width:100%;height:auto;display:block;margin:20px auto;border-radius:2px;}\n#wemd table{width:100%;border-collapse:collapse;margin:20px 0;font-size:13px;border:1px solid #E4E4E7;background:#FFFFFF;}\n#wemd th{padding:10px 12px;background:#FAFAFA;border-bottom:2px solid #52525B;text-align:left;font-weight:700;color:#27272A;font-size:12px;}\n#wemd td{padding:10px 12px;border-bottom:1px solid #E4E4E7;color:#52525B;}\n#wemd hr{border:none;height:1px;background:#E4E4E7;margin:32px 0;}",
